// SINGLE PLACE for dashboard alert thresholds.
// Keep BENCH_TIMING equal to `#define BENCH_TIMING` in firmware/node1_fridge/node1_fridge.ino
//   1 = desk test timings (28 °C / 10 s, door 15 s)
//   0 = real clinic timings for SR-13 (8 °C / 10 min, door 5 min)
const BENCH_TIMING = 1;

const cfg = {
    bench: BENCH_TIMING === 1,
    tempLowC: 2.0,                          // below this = freeze risk (dashboard-only rule)
    tempHighC: BENCH_TIMING ? 28.0 : 8.0,   // firmware TEMP_HIGH_C
    tempAlarmS: BENCH_TIMING ? 10 : 600,    // firmware TEMP_ALARM_MS / 1000
    doorAlarmS: BENCH_TIMING ? 15 : 300,    // firmware DOOR_ALARM_MS / 1000
    staleS: 15,                             // firmware publishes every 5 s -> 3 missed messages
    offlineS: 30                            // 6 missed messages
};
flow.set('cfg', cfg);
node.status({ fill: cfg.bench ? 'yellow' : 'green', shape: 'dot',
    text: `${cfg.bench ? 'BENCH' : 'CLINIC'} · ${cfg.tempLowC}–${cfg.tempHighC} °C · door ${cfg.doorAlarmS} s` });

