// Renders the Node 1 banner + door row from flow 's1'. Runs on every update and on the 1 s tick,
// so the door timer counts live and the watchdog marks the node STALE / OFFLINE when it goes silent.
// Outputs: 1 = banner, 2 = door row, 3 = events (-> Event Log)
const cfg = flow.get('cfg');
const s = flow.get('s1') || {};
const now = Date.now();
const fmt = sec => `${Math.floor(sec / 60)}:${String(sec % 60).padStart(2, '0')}`;
const clock = t => new Date(t).toLocaleTimeString();

if (!context.get('since')) context.set('since', now);
const age = Math.floor((now - (s.lastSeen || context.get('since'))) / 1000);
const health = s.lwtOffline || age >= cfg.offlineS ? 'OFFLINE'
    : !s.lastSeen ? 'WAITING'
    : age >= cfg.staleS ? 'STALE' : 'ONLINE';

const events = [];
const prevHealth = context.get('health');
if (health !== prevHealth) {
    if (health === 'STALE') events.push({ sev: 'WARN', src: 'watchdog', text: `Node 1 telemetry STALE: no message for ${age} s` });
    if (health === 'OFFLINE' && !s.lwtOffline) events.push({ sev: 'CRITICAL', src: 'watchdog', text: `Node 1 OFFLINE: no message for ${age} s` });
    if (health === 'ONLINE' && (prevHealth === 'STALE' || prevHealth === 'OFFLINE')) events.push({ sev: 'INFO', src: 'watchdog', text: 'Node 1 back online' });
    context.set('health', health);
}

const RED = ['#7f1d1d', '#ef4444'], ORANGE = ['#7c2d12', '#f97316'], AMBER = ['#78350f', '#f59e0b'],
      BLUE = ['#1e3a8a', '#60a5fa'], GREEN = ['#064e3b', '#10b981'], GREY = ['#1e293b', '#334155'];
const banner = (c, title, sub) => ({ bg: c[0], bd: c[1], title, sub });

const doorSec = s.door === 'OPEN' && s.doorOpenedAt ? Math.max(0, Math.floor((now - s.doorOpenedAt) / 1000)) : 0;
const doorTxt = s.door === 'OPEN' ? `Door OPEN ${fmt(doorSec)}` : 'Door closed';
const t = Number.isFinite(s.temp) ? `${s.temp.toFixed(2)} °C` : '-- °C';

let b, doorRow;
if (health === 'WAITING') {
    b = banner(GREY, 'Waiting for Node 1...', `No telemetry yet · watchdog trips at ${cfg.offlineS} s`);
    doorRow = 'WAITING';
} else if (health === 'OFFLINE') {
    b = banner(RED, 'NODE 1 OFFLINE',
        `${s.lwtOffline ? 'LWT received' : `Silent for ${fmt(age)}`} · last data ${s.lastSeen ? clock(s.lastSeen) : 'never'}`);
    doorRow = 'UNKNOWN (offline)';
} else {
    if (s.alarm === 'BREACH') b = banner(RED, 'SECURITY BREACH ACTIVE', `Buzzer + Red LED locked ON · seq #${s.seq}`);
    else if (s.temp < cfg.tempLowC) b = banner(BLUE, `FREEZE RISK: BELOW ${cfg.tempLowC} °C`, `${t} · vaccines may be damaged · ${doorTxt}`);
    else if (s.alarm === 'TEMP') b = banner(ORANGE, 'OVER-TEMPERATURE ALARM', `${t} above ${cfg.tempHighC} °C for ${cfg.tempAlarmS} s+ · ${doorTxt}`);
    else if (s.temp > cfg.tempHighC) b = banner(AMBER, `WARNING: ABOVE ${cfg.tempHighC} °C`, `${t} · alarm after ${cfg.tempAlarmS} s · ${doorTxt}`);
    else if (s.alarm === 'DOOR') b = banner(ORANGE, `DOOR ALARM (${fmt(doorSec)})`, `Close vaccine fridge door · buzzer sounding · ${t}`);
    else if (s.door === 'OPEN') b = banner(AMBER, `DOOR OPEN (${fmt(doorSec)})`, `Alarm at ${fmt(cfg.doorAlarmS)} · ${t}`);
    else b = banner(GREEN, `COLD-CHAIN SAFE (${cfg.tempLowC}–${cfg.tempHighC} °C)`, `${t} · Door closed`);

    b.sub += ` · ${clock(s.lastSeen)}`;
    if (health === 'STALE') {
        b.title = `STALE DATA · ${b.title}`;
        b.sub = `No message for ${age} s · ${b.sub}`;
        b.bd = '#eab308';
    }
    doorRow = s.door === 'OPEN' ? `OPEN (${fmt(doorSec)})` : 'CLOSED';
}
if (cfg.bench) b.sub += ' · BENCH TIMING';

// Only send what changed, so the 1 s tick does not flood the dashboard.
const out = [null, null, events.length ? { events } : null];
const bKey = JSON.stringify(b);
if (bKey !== context.get('lastBanner')) { context.set('lastBanner', bKey); out[0] = { payload: b }; }
if (doorRow !== context.get('lastDoor')) { context.set('lastDoor', doorRow); out[1] = { payload: doorRow }; }
return out;

// Renders the Node 2 banner + heartbeat row from flow 's2'. Runs on every update and on the 1 s tick:
// live power-cut timer, live "seconds since last message", and STALE / OFFLINE watchdog.
// Outputs: 1 = banner, 2 = heartbeat row, 3 = events (-> Event Log)
const cfg = flow.get('cfg');
const s = flow.get('s2') || {};
const now = Date.now();
const fmt = sec => `${Math.floor(sec / 60)}:${String(sec % 60).padStart(2, '0')}`;
const clock = t => new Date(t).toLocaleTimeString();

if (!context.get('since')) context.set('since', now);
const age = Math.floor((now - (s.lastSeen || context.get('since'))) / 1000);
const health = s.lwtOffline || age >= cfg.offlineS ? 'OFFLINE'
    : !s.lastSeen ? 'WAITING'
    : age >= cfg.staleS ? 'STALE' : 'ONLINE';

const events = [];
const prevHealth = context.get('health');
if (health !== prevHealth) {
    if (health === 'STALE') events.push({ sev: 'WARN', src: 'watchdog', text: `Node 2 telemetry STALE: no message for ${age} s` });
    if (health === 'OFFLINE' && !s.lwtOffline) events.push({ sev: 'CRITICAL', src: 'watchdog', text: `Node 2 OFFLINE: no message for ${age} s (SR-14)` });
    if (health === 'ONLINE' && (prevHealth === 'STALE' || prevHealth === 'OFFLINE')) events.push({ sev: 'INFO', src: 'watchdog', text: 'Node 2 back online' });
    context.set('health', health);
}

const banner = (c, title, sub) => ({ bg: c[0], bd: c[1], title, sub });
let b, hb;
if (health === 'WAITING') {
    b = banner(['#1e293b', '#334155'], 'Waiting for Node 2...', `No telemetry yet · watchdog trips at ${cfg.offlineS} s`);
    hb = 'WAITING';
} else if (health === 'OFFLINE') {
    b = banner(['#7f1d1d', '#ef4444'], 'NODE 2 OFFLINE (SR-14 ALERT)',
        `${s.lwtOffline ? 'LWT received' : `Silent for ${fmt(age)}`} · power monitoring lost`);
    hb = `OFFLINE · last seq #${s.seq ?? '-'} at ${s.lastSeen ? clock(s.lastSeen) : 'never'}`;
} else {
    b = s.mainsOn
        ? banner(['#064e3b', '#10b981'], 'MAINS POWER ON (230 V OK)', `seq #${s.seq} · Node 2 healthy`)
        : banner(['#7f1d1d', '#ef4444'], `POWER CUT DETECTED (${fmt(Math.max(0, Math.floor((now - s.cutAt) / 1000)))})`,
            'Backup battery active · Buzzer sounding');
    if (health === 'STALE') {
        b.title = `STALE DATA · ${b.title}`;
        b.sub = `No message for ${age} s · ${b.sub}`;
        b.bd = '#eab308';
    }
    hb = `seq #${s.seq} · ${age} s ago`;
}

const out = [null, null, events.length ? { events } : null];
const bKey = JSON.stringify(b);
if (bKey !== context.get('lastBanner')) { context.set('lastBanner', bKey); out[0] = { payload: b }; }
if (hb !== context.get('lastHb')) { context.set('lastHb', hb); out[1] = { payload: hb }; }
return out;

// Single owner of the SOC security event log, persisted in the 'file' context store.
// Inputs:  msg.events = [{sev, src, text}] or msg.event   -> append, broadcast newest VIEW rows
//          msg.topic 'refresh' (from a dashboard client) -> newest VIEW rows to that client only
//          msg.topic 'export'  (from a dashboard client) -> all stored rows to that client only
// Retention: 90 days and at most MAX rows (M12: no personal data is logged, only device events).
const KEEP_MS = 90 * 24 * 3600 * 1000, MAX = 1000, VIEW = 100;

let logs = flow.get('eventLog', 'file') || [];

if (msg.topic === 'export') return { topic: 'export', payload: logs, socketid: msg.socketid };
if (msg.topic === 'refresh') return { topic: 'log', payload: logs.slice(0, VIEW), socketid: msg.socketid };

const incoming = msg.events || (msg.event ? [msg.event] : []);
if (!incoming.length) return null;

const now = Date.now();
for (const e of incoming) logs.unshift({ ts: now, sev: e.sev, src: e.src, text: e.text });
logs = logs.filter(l => now - l.ts <= KEEP_MS).slice(0, MAX);
flow.set('eventLog', logs, 'file');
node.status({ text: `${logs.length} events stored` });
return { topic: 'log', payload: logs.slice(0, VIEW) };

// Owns the fridge temperature log (last 24 h, one sample per minute), persisted in the 'file' store.
// Inputs:  msg.payload = temperature (from Process Node 1; door/alarm/seq read from flow 's1')
//          msg.topic 'export' (from a dashboard client) -> all rows to that client only
// The full-rate history stays in Mobius/MySQL; this is the clinic's quick daily record.
const KEEP_MS = 24 * 3600 * 1000, EVERY_MS = 60 * 1000;

let log = flow.get('fridgeLog', 'file') || [];
if (msg.topic === 'export') return { topic: 'export', payload: log, socketid: msg.socketid };

const now = Date.now();
if (log.length && now - log[log.length - 1].ts < EVERY_MS) return null;

const s = flow.get('s1') || {};
log.push({ ts: now, temp: msg.payload, door: s.door, alarm: s.alarm, seq: s.seq });
log = log.filter(r => now - r.ts <= KEEP_MS);
flow.set('fridgeLog', log, 'file');
node.status({ text: `${log.length} samples (24 h)` });
return null;
